import sys

def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    vals = list(map(int, data[2:2 + n * m]))
    cols = [vals[j::m] for j in range(m)]
    rowmax = [max(vals[i * m:(i + 1) * m]) for i in range(n)]
    best_possible = min(rowmax)

    def two_disjoint(edges):
        if len(edges) < 2:
            return False
        common = None
        verts = set()
        for e in edges:
            s = set(e)
            verts |= s
            common = s if common is None else (common & s)
        if common:
            return False
        if len(edges) == 3 and len(verts) == 3:
            return False
        return True

    def feasible(x):
        if best_possible < x:
            return False
        edges = set()
        for col in cols:
            idx = [i for i, v in enumerate(col) if v >= x]
            if len(idx) >= 3:
                return True
            if len(idx) == 2:
                edges.add((idx[0], idx[1]))
        return two_disjoint(edges)

    cand = sorted(set(vals))
    lo, hi = 0, len(cand) - 1
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(cand[mid]):
            lo = mid
        else:
            hi = mid - 1
    print(cand[lo])

main()

